import {ingredients,recipes,exercises,sources,exerciseVideos,cookingVideos,cookingSearch} from './content.js';
import * as C from './core.js';
const KEY='afterhours.v1', $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let waitingUpdate=null;
let theme='system';try{theme=localStorage.getItem('afterhours.theme')||'system';}catch{}
function applyTheme(){document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;}
applyTheme();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
let state=C.fresh(),storageError='',view=location.hash.slice(1)||'today',selectedDay='',mealTab='plan',undoState=null,draft=null,step=0,activeRecipe=null,recipeServings=1,session=null;
try{const raw=localStorage.getItem(KEY);if(raw)state=C.validateBackup(JSON.parse(raw));}catch(e){storageError='Your saved data could not be loaded. It has not been overwritten. Export the recovery file in Settings before starting again.';}
const icons={today:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',training:'<path d="m6 6 12 12M4 9l5-5m6 16 5-5M2 7l5-5m10 20 5-5"/>',meals:'<path d="M6 3v7m-3-7v5a3 3 0 0 0 6 0V3M6 11v10M17 3c-3 3-3 8 1 9V3h1v18"/>',progress:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 3v4l3 1 2 3 3-2 4 1 1-3 3-2-2-3 1-4-3-1-2-3z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3zM12 6v15"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.today}</svg>`;
const btn=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const region=()=>state.region||{...C.regionDefaults,city:state.profile?.city||'manila'};
const money=n=>C.formatMoney(n,region());
const amount=n=>+(n*region().rate).toFixed(4);
const baseAmount=n=>Number(n)/region().rate;
const fmt=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'pm':'am'}`;};
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en',{weekday:'short',month:'short',day:'numeric',timeZone:'UTC'});
const today=()=>C.wakingDay({...(state.profile||C.defaults),city:region().city});
const day=()=>state.plan?.days.find(d=>d.day===(selectedDay||today()));
const doneWorkout=d=>state.workouts.find(w=>w.day===d);
const field=(label,name,value,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,value,options)=>`<label>${label}<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;
const check=(label,name,checked,value='yes')=>`<label class="check"><input type="checkbox" name="${name}" value="${value}" ${checked?'checked':''}><span>${label}</span></label>`;
function toast(text,undo=false){$('#toast').innerHTML=`${esc(text)} ${undo?btn('Undo','undo','','text-btn'):''}`;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),8000);}
function save(text,fn){if(storageError){toast('Export your recovery file and reset storage before making changes.');return false;}const previous=structuredClone(state);try{fn?.();state.calendarRevision++;localStorage.setItem(KEY,JSON.stringify(state));undoState=previous;render();if(text)toast(text,true);return true;}catch(e){state=previous;toast('Could not save: '+e.message);return false;}}
function modal(html){const el=$('#modal');el.innerHTML=`<button class="close" data-action="close" aria-label="Close dialog">×</button>${html}`;if(!el.open)el.showModal();el.querySelector('h2')?.setAttribute('tabindex','-1');}
function close(){ $('#modal').close(); }
function week(){return state.plan?`<div class="week" aria-label="Waking days">${state.plan.days.map(d=>`<button data-action="day" data-day="${d.day}" class="${d.day===(selectedDay||today())?'selected':''}" aria-pressed="${d.day===(selectedDay||today())}"><span>${new Date(d.day+'T12:00Z').toLocaleDateString('en',{weekday:'short',timeZone:'UTC'})}</span><strong>${Number(d.day.slice(-2))}</strong><i class="${doneWorkout(d.day)?'complete':d.workout?'train':''}"></i></button>`).join('')}</div>`:'';}
function shell(content){const labels=['today','training','meals','progress','settings'];return `<aside class="sidebar"><a href="#today" class="brand"><span class="brand-mark">a</span>afterhours fitness</a><div class="side-label">PLAN · LOG · REVIEW</div><nav>${labels.map(n=>`<a href="#${n}" class="${view===n?'active':''}">${icon(n)}<span>${n[0].toUpperCase()+n.slice(1)}</span>${view===n?'<b></b>':''}</a>`).join('')}</nav><div class="side-bottom"><button class="local-badge plain" data-action="region" aria-label="Change time zone and currency">${icon('moon')}<div>Schedule settings<small>Local time · ${region().currency}<br>Change time zone or currency</small></div></button><div class="private-note">Records are stored in this browser.<br>${navigator.onLine?'No account · No analytics':'Offline · Saved records available'}</div></div></aside><main><header class="topbar"><span>${view[0].toUpperCase()+view.slice(1)}</span><div><button class="zone plain" data-action="region">LOCAL TIME · ${region().currency}</button><span class="avatar">${icon('moon')}</span></div></header><div class="page">${storageError?`<div class="notice danger">${storageError}</div>`:''}${content}</div><footer>Afterhours Fitness <span>METHODS REVIEWED · SEP 2026</span></footer></main>`;}
function title(kicker,title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function methodSummary(){return `<section class="method-card"><div class="method-head"><div><p class="eyebrow">PLAN BASIS</p><h2>What the calculations use</h2></div><span class="reviewed">Reviewed 22 Sep 2026</span></div><div class="method-grid"><a href="https://pubmed.ncbi.nlm.nih.gov/41843416/" target="_blank" rel="noopener noreferrer"><span>TRAINING</span><strong>ACSM position stand</strong><small>Overview of 137 systematic reviews</small></a><a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener noreferrer"><span>WEEKLY ACTIVITY</span><strong>CDC adult guidance</strong><small>Cardio and muscle-strengthening minimums</small></a><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer"><span>ENERGY</span><strong>Mifflin–St Jeor equation</strong><small>Resting-energy estimate, published 1990</small></a><a href="https://fdc.nal.usda.gov/download-datasets/" target="_blank" rel="noopener noreferrer"><span>FOOD DATA</span><strong>USDA FoodData Central</strong><small>Ingredient energy and protein records</small></a></div><p class="method-foot">The app applies these references through documented planning rules. It does not claim that this specific program was tested as a complete intervention.</p></section>`;}
function setupEmpty(){return `${title('SETUP','Build your weekly plan.','Enter your schedule, available equipment, food preferences, and budget.')}<div class="welcome-grid"><section class="hero"><div class="pill">${icon('moon')} SETUP TAKES ABOUT 5 MINUTES</div><h2>Start with your<br>waking hours.</h2><p>The planner places three meals and your selected training days inside the hours you are awake. You review the full week before anything is saved.</p>${btn('Set up my plan '+icon('arrow'),'setup','','primary lime')}<div class="hero-foot">Measurements are optional <span>•</span> Records stay in this browser</div></section><section class="card setup-card"><p class="eyebrow">HOW SCHEDULING WORKS</p><h2>Your wake time anchors the plan.</h2><div class="rhythm-row"><span class="rhythm-icon">${icon('moon')}</span><div><strong>Wake time</strong><p>Starts your personal planning day</p></div></div><div class="rhythm-row"><span class="rhythm-icon">${icon('training')}</span><div><strong>Workout window</strong><p>Placed before work when the full session fits</p></div></div><div class="rhythm-row"><span class="rhythm-icon">${icon('clock')}</span><div><strong>Meal times</strong><p>Spread across the hours you are awake</p></div></div><p class="small muted">Suggested times are scheduling rules, not physiological predictions. Every time remains editable.</p></section></div><div class="section-head"><h2>Included in your plan</h2><span class="muted">No records yet</span></div><div class="three-grid">${[['training','Strength sessions','Equipment-aware movements, technique cues, and set logging.'],['meals','Meals and groceries','Ten recipes, adjustable portions, and one weekly shopping list.'],['progress','Check-ins and review','Weight, hunger, energy, and training history reviewed over time.']].map(([i,t,s])=>`<section class="card intro-card"><span class="intro-icon">${icon(i)}</span><h3>${t}</h3><p class="muted">${s}</p></section>`).join('')}</div>`;}
function todayPage(){if(!state.profile)return setupEmpty();const d=day(),p=state.profile,completed=d&&doneWorkout(d.day);if(!d)return `${title('THIS WEEK', 'Review your next seven days.', 'Your previous records are saved.')}<section class="card">${btn('Review next 7 days','renew','','primary')}</section>`;const logs=state.mealLogs.filter(x=>x.day===d.day),habits=state.habits[d.day]||{},xp=C.journey(state).xp;const t=state.plan.targets,totals=logs.reduce((a,m)=>{const n=m.nutrition||C.nutrition(C.recipe(m.recipe),m.servings,p);a.kcal+=n.kcal;a.protein+=n.protein;return a;},{kcal:0,protein:0});return `${title('TODAY · '+dateLabel(d.day),'Your plan for this waking day.','Meals and training stay attached to the day you woke, including items after midnight.',`<div class="button-row">${btn('Review timing','suggesttiming','','outline')}${btn(icon('plus')+' Check in','checkin','','outline')}</div>`)}${week()}${d.scheduleWarning?`<p class="notice danger">${esc(d.scheduleWarning)}</p>`:''}<div class="today-grid"><section class="hero compact"><div class="pill">${icon(completed?'check':d.workout?'training':'moon')} ${completed?'SESSION SAVED':d.workout?'STRENGTH SESSION':'NO STRENGTH SESSION'}</div><h2>${completed?'Session complete.':d.workout?'Today’s strength session.':'No strength session today.'}</h2><p>${d.workout?`${d.workout.duration} minutes · Full body · ${d.workout.light?'Lighter session':p.equipment.includes('dumbbell')?'Dumbbells and bodyweight':'Bodyweight'}`:'Optional easy movement and your usual recovery routine. No strength session is scheduled.'}</p><div class="hero-actions">${btn(completed?'View saved session '+icon('arrow'):d.workout?'Start workout '+icon('arrow'):'Log recovery '+icon('check'),completed?'history':d.workout?'start':'recovery',`data-day="${d.day}"`,'primary lime')}${d.workout&&!completed?btn('Change time','reschedule',`data-day="${d.day}"`,'ghost'):''}</div><div class="hero-foot">${icon('clock')} ${d.workout?fmt(d.workout.time)+' · '+esc(d.workout.note):'No workout scheduled.'}</div></section><section class="card daily-focus"><p class="eyebrow">NUTRITION LOG</p><h2>${t?'Today’s estimated intake':'Meals logged today'}</h2><div class="fuel-number">${t?Math.round(totals.protein)+'<small> / '+t.protein+' g protein</small>':logs.length+'<small> / '+d.meals.length+' meals logged</small>'}</div><div class="bar"><span style="width:${Math.min(100,t?totals.protein/t.protein*100:logs.length/Math.max(1,d.meals.length)*100)}%"></span></div><p class="small muted">${t?Math.round(totals.kcal)+' / '+t.kcal+' estimated kcal · planned-meal logs only':'Habit-only mode. No calorie target is used.'}</p><div class="focus-tip">${icon('book')}<p>Your next planned meal is listed below. Times and portions can be changed from Meals.</p></div>${btn('Log other food','food','','text-btn')}</section></div><div class="two-grid"><section class="card"><div class="section-head"><h2>Planned meals</h2><a href="#meals">Open meal plan ${icon('arrow')}</a></div>${d.meals.length?d.meals.map(m=>mealRow(m,d.day)).join(''):'<p class="notice">No recipes match all your restrictions. Review food preferences in Settings; restrictions will not be relaxed.</p>'}</section><section class="card"><div class="section-head"><h2>Daily checklist</h2><span class="tag">${Object.values(habits).filter(Boolean).length}/3</span></div>${[['water','Keep drinking water available'],['sleep','Protect my sleep window'],['recovery','Move or recover intentionally']].map(([id,label])=>`<button class="habit ${habits[id]?'checked':''}" data-action="habit" data-id="${id}" data-day="${d.day}"><span class="checkbox">${habits[id]?icon('check'):''}</span><span>${label}</span><small>+10 XP</small></button>`).join('')}${p.journey?`<div class="journey"><div><span class="eyebrow">OPTIONAL PROGRESSION</span><strong>${xp} XP <small>· ${C.journey(state).rank}</small></strong></div><span class="journey-badge">${C.journey(state).index+1}</span></div><p class="small muted">Day ${Math.max(1,Math.floor((Date.parse(d.day+'T12:00Z')-Date.parse(state.created))/86400000)+1)} of the optional 66-day tracker. Missed days do not remove saved progress.</p>`:''}</section></div>`;}
function mealRow(m,d){const r=C.recipe(m.recipe),n=C.nutrition(r,m.servings,state.profile),done=state.mealLogs.some(l=>l.id===m.id);return `<div class="meal-row"><span class="meal-time">${fmt(m.time)}${C.mins(m.time)<C.mins(C.settingsFor(state.profile,d).wake)?'<small>next calendar day</small>':''}</span><div class="meal-detail"><button class="plain" data-action="recipe" data-id="${r.id}" data-servings="${m.servings}">${r.name}</button><p>${Math.round(n.kcal)} kcal · ${Math.round(n.protein)} g protein · ${money(n.cost)} <span class="small">est.</span></p></div>${btn(done?icon('check'):icon('plus'),'logmeal',`data-id="${m.id}" data-day="${d}" aria-label="${done?'Undo meal log':'Log '+r.name}"`,done?'circle checked':'circle')}</div>`;}
function trainingEvidence(){return `<details class="card"><summary>Training method and evidence</summary><p>The <a href="https://pubmed.ncbi.nlm.nih.gov/41843416/" target="_blank" rel="noopener noreferrer">2026 ACSM position stand</a> synthesized 137 systematic reviews covering more than 30,000 adults. It found that progressive resistance training improves strength and other measures of physical function. Strength outcomes were enhanced by complete range of motion, 2–3 sets, and at least two sessions per week. <a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener noreferrer">CDC guidance</a> also recommends muscle-strengthening work for all major muscle groups on at least two days each week.</p><p>Afterhours uses three selectable, nonconsecutive training days; one squat, hinge, push, pull, and trunk movement; 2–3 working sets; and load increases only after the saved sets reach the top of the repetition range with controlled form and effort at or below 8/10. These are implementation choices based on the broader evidence. This exact program has not been tested as a complete intervention.</p><p>Technique videos are demonstrations. Stop a movement that causes pain and seek qualified help for an injury or medical restriction.</p></details>`;}
function foodEvidence(r){return `<details class="card"><summary>Nutrition sources & estimate limits</summary><p>Energy and protein inputs come from the <a href="https://fdc.nal.usda.gov/download-datasets/" target="_blank" rel="noopener noreferrer">official USDA FoodData Central SR Legacy dataset (April 2018)</a>, extracted and checked September 21, 2026. Recipe totals sum the ingredient quantities; the finished meals have not been laboratory-tested.</p><p>Each link below identifies the actual food record used. Proxy matches are flagged. Local brands, produce, drained weights, cooking losses, and oil left in the pan can change totals. Philippine-specific records were not available for verified extraction from <a href="https://i.fnri.dost.gov.ph/fct/library" target="_blank" rel="noopener noreferrer">PhilFCT</a>. Prices and household measures remain estimates, not research findings.</p>${Object.keys(r.items).map(id=>{const i=ingredients[id],v=i.nutritionSource;return `<div class="nutrient-source"><a href="${v.url}" target="_blank" rel="noopener noreferrer">${i.name} · USDA food record</a><p class="small">${esc(v.description)}<br>${v.kcal} kcal · ${v.protein} g protein per 100 g<br>${esc(v.note)}</p></div>`;}).join('')}</details>`;}
function tdeeResult(p){const n=C.energyEstimate(p);if(!n)return `<p class="notice">Enter adult age, height, weight, activity level, and an equation coefficient to calculate. Height and weight alone are not enough for this equation.</p>`;return `<div class="review-summary"><div><span>Estimated TDEE / maintenance</span><strong>${n.tdee.toLocaleString()} kcal per day</strong></div><div><span>Estimated resting energy</span><strong>${n.resting.toLocaleString()} kcal per day</strong></div><div><span>${p.goal==='fat loss'?'Suggested starting target (10% below estimate)':'Suggested starting target (rounded maintenance)'}</span><strong>${n.kcal.toLocaleString()} kcal per day</strong></div></div><p class="small muted">TDEE is an estimate of total daily energy expenditure, not a measurement. Activity factors are planning assumptions. The formula estimates resting needs first, then multiplies by activity. <a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer">Mifflin–St Jeor study</a>. Protein guidance uses <a href="https://pubmed.ncbi.nlm.nih.gov/28698222/" target="_blank" rel="noopener noreferrer">Morton et al.’s resistance-training review</a>. Individual needs vary.</p>`;}
function openTDEE(){const p=state.profile||C.defaults;modal(`<p class="eyebrow">CALCULATES AS YOU TYPE</p><h2>Your TDEE estimate</h2><form id="tdee-form"><div class="form-grid">${field('Height (cm)','height',p.height,'number','min="120" max="230" required')}${field('Weight (kg)','weight',p.weight,'number','min="30" max="300" step=".1" required')}${field('Age (years)','age',p.age,'number','min="18" max="100" required')}${select('Equation coefficient','sex',p.sex,[['','Choose a coefficient'],['female','Female coefficient (−161)'],['male','Male coefficient (+5)']])}${select('Activity outside workouts','activity',p.activity,[[1.2,'Mostly sitting'],[1.4,'Lightly active'],[1.6,'Moderately active']])}${select('Priority for suggested target','goal',p.goal,['consistency','fat loss','build muscle'])}</div><div id="tdee-result" aria-live="polite">${tdeeResult(p)}</div><p class="small muted">Typing does not change your saved plan. ${state.profile?'Save only if you want to use these estimates. Existing meal portions stay editable and will not be silently changed.':'Finish personal setup to use estimates in a plan.'}</p>${state.profile?'<button class="primary" type="submit">Use this estimate for my targets</button>':''}</form>`);}
function videoPlayer(v,label){if(!v?.youtube)return '';return `<details class="video-player" data-video="${v.youtube}"><summary>▷ Play ${esc(label)} here</summary><div class="video-slot"></div><p class="small muted">Online video from ${esc(v.source)}. If the publisher blocks playback here, use the source link below. Written instructions work offline.</p></details>`;}
function formVideo(e){const v=exerciseVideos[e.id];return v?`<div class="video-guide">${videoPlayer(v,e.name+' tutorial')}<a href="${v.url}" target="_blank" rel="noopener noreferrer">Watch form video at source</a><span class="small muted"> · ${v.source}</span>${v.note?`<p class="small muted">${v.note}</p>`:''}</div>`:'';}
function cookingGuide(r){const v=cookingVideos[r.id];return `<section class="cooking-guide"><h3>See how it’s cooked</h3>${videoPlayer(v,v?.label||'cooking tutorial')}${v?.note?`<p class="notice">${esc(v.note)}</p>`:''}<div class="button-row">${v?`<a class="button outline" href="${v.url}" target="_blank" rel="noopener noreferrer">Open video at source</a>`:''}<a class="button outline" href="${cookingSearch(r)}" target="_blank" rel="noopener noreferrer">Find cooking videos on YouTube</a></div><p class="small muted">Related techniques, not the exact Afterhours recipe. Videos may use different ingredients, allergens, oil, and portions. Follow the ingredient list here for your plan. Videos require internet and load from YouTube when opened.</p></section>`;}
function trainingPage(){if(!state.profile)return setupEmpty();const p=state.profile,d=day(),r=C.routine(p,d?.workout?.light||d?.workout?.duration<25),last=state.workouts.at(-1);return `${title('TRAINING','Strength plan.','Full-body sessions selected from your equipment and movement limits.',btn('Edit my routine','setup','','outline'))}${week()}<div class="training-banner"><div><span class="eyebrow">${d?.workout?'FULL BODY · '+fmt(d.workout.time):'RECOVERY DAY'}</span><h2>${d?.workout?`${d.workout.duration}-minute ${d.workout.light?'lighter':'strength'} session`:'Make space to recover'}</h2><p>${d?.workout?esc(d.workout.note):'Your next strength day is marked in the week above.'}</p></div><div class="button-row">${d?.workout&&!doneWorkout(d.day)?btn('Start session '+icon('arrow'),'start','','primary'):''}${d?.workout&&!doneWorkout(d.day)?btn(d.workout.light?'Use regular session':'Take it lighter','light','','outline'):''}</div></div>${last&&Date.parse((selectedDay||today())+'T12:00Z')-Date.parse(last.day+'T12:00Z')>14*86400000?'<p class="notice">Returning after a break? Use a lighter session and a comfortable load. Build back over several sessions.</p>':''}${trainingEvidence()}<div class="section-head"><h2>The movements</h2><span class="muted">5-minute warm-up included · gentle practice sets</span></div>${p.otherLimit?'<p class="notice danger">Your written limitation needs individual review. Automatic exercise selection is paused; the app cannot safely interpret medical or movement restrictions.</p>':''}${r.length?r.map((e,i)=>{const prev=C.previousPerformance(state.workouts,e.id);return `<section class="exercise-card"><span class="exercise-num">${String(i+1).padStart(2,'0')}</span><div class="exercise-main"><span class="eyebrow">${e.pattern}</span><h3>${e.name}</h3><p>${e.cues}</p>${formVideo(e)}<div class="exercise-meta"><span>${e.sets} sets × ${e.reps.join('–')} reps</span><span>${e.rest}s rest</span><span>${e.unit}</span></div><p class="small muted">Previous: ${prev?prev.sets.map(s=>`${s.reps} × ${s.weight} kg · effort ${s.rpe}`).join(' / '):'Your first session will set the baseline.'}</p></div></section>`;}).join(''):'<section class="card"><p>No compatible movements. Review equipment and limitations.</p></section>'}<details class="card"><summary>How progression works</summary><p>Choose a load that leaves about 2–3 repetitions in reserve (effort 7–8 out of 10). Once all planned sets reach the top of the rep range with reported controlled form at effort 8 or less, the app suggests the next weight from your available list, respecting your minimum increment. Otherwise, repeat the load. Stop a movement if it hurts.</p><p>Lighter sessions use two sets. After a break, start comfortably and build back. Three nonconsecutive strength days are suggested; edit them during setup. Barbell work is not prescribed because this app cannot confirm rack, safeties, or spotter availability.</p></details><div class="section-head"><h2>Completed sessions</h2><span>${state.workouts.length} saved</span></div>${state.workouts.length?[...state.workouts].reverse().slice(0,20).map(w=>`<button class="history-row" data-action="history" data-day="${w.day}"><span>${icon('check')} Full body · ${dateLabel(w.day)}</span><span>${w.exercises.length} movements ${icon('arrow')}</span></button>`).join(''):'<p class="muted">Your completed sessions will appear here.</p>'}`;}
function foodFilterStatus(){const rules=C.allergyRules(state.profile),results=C.recipeEligibility(state.profile),count=results.filter(x=>!x.reasons.length).length;return `<div class="notice"><strong>${count} of ${results.length} recipes match your settings</strong><p class="small">${rules.allergens.length?'Excluded: '+esc(rules.allergens.join(', '))+'.':'No listed allergens excluded.'} ${rules.recognized.length?'Recognized allergy text: '+esc(rules.recognized.join(', '))+'.':''} ${rules.recognized.some(x=>['seafood','seafoods'].includes(x))?'Seafood excludes both fish and shellfish.':''}</p>${rules.unknown.length?`<p>Menu generation is paused for allergy terms the app cannot interpret: <strong>${esc(rules.unknown.join(', '))}</strong>. Review these terms; do not remove a genuine allergy just to generate a menu.</p>`:''}${!count?`<details><summary>Why recipes are excluded</summary>${results.map(x=>`<p><strong>${x.recipe.name}</strong>: ${esc(x.reasons.join('; '))}</p>`).join('')}</details>`:''}${btn('Review food filters','foodfilters','','text-btn')}<p class="small muted">Matches are based on listed ingredients. Check package labels and cross-contact; recipe videos may add excluded ingredients.</p></div>`;}
function foodFilters(){const p=state.profile;modal(`<h2>Food filters</h2><p>Checked items are excluded, not preferred foods. Changes update only your food filters and upcoming unlogged meals.</p><form id="foodfilters-form"><label><strong>Foods to EXCLUDE</strong> — leave unchecked if you eat them</label><p class="small muted">Checking a food removes recipes containing it. These are not foods you want included.</p><div class="check-grid">${['egg','soy','fish','gluten','legume','milk','peanut','tree nut','shellfish','sesame'].map(a=>check(a,'allergies',p.allergies.includes(a),a)).join('')}</div>${field('Other allergies (comma-separated)','otherAllergy',p.otherAllergy,'text','maxlength="500"')}<p class="small muted">Seafood means fish and shellfish. Unrecognized terms pause recommendations until reviewed.</p>${field('Ingredients to avoid (comma-separated names)','avoid',p.avoid,'text','maxlength="500"')}${select('Food preference','diet',p.diet,[['any','No dietary preference'],['vegetarian','Vegetarian (eggs allowed)']])}${field('Maximum recipe time (minutes)','prepTime',p.prepTime,'number','min="5" max="180" required')}<label>Cooking and storage equipment</label><div class="check-grid">${['stove','rice cooker','microwave','fridge'].map(k=>check(k,'kitchen',p.kitchen.includes(k),k)).join('')}</div><button class="primary" type="submit">Save filters & refresh meals</button></form>`);}
function mealRecommendations(){const r=C.recommendMeals(state.profile,state.favorites);return `<section class="card"><div class="section-head"><div><p class="eyebrow">FILTERED RECIPE SET</p><h2>Meal suggestions</h2></div>${btn('Choose recipes','choose-recipes','','outline')}</div>${foodFilterStatus()}<p>${r.chosen?'Your selected recipes are used first. Breakfast recipes fill the first meal; main dishes fill later meals. Other compatible recipes fill remaining slots.':'Suggestions are filtered by declared allergens, avoided foods, diet, kitchen equipment, maximum preparation time, pantry items, and budget mode.'}</p>${r.blocked.length?`<p class="notice">${r.blocked.length} selected recipe(s) do not match the current restrictions, equipment, or preparation time and will not be scheduled.</p>`:''}<div class="recipe-grid">${r.recipes.map(x=>`<article><span class="tag">${r.chosen?'★ Selected':'Matches filters'}</span><h3>${x.name}</h3><p class="small muted">${x.time} min · ${money(C.nutrition(x,1,state.profile).cost)} per portion, estimated</p>${btn('View recipe','recipe',`data-id="${x.id}"`,'text-btn')}</article>`).join('')||'<p>No recipes match the current settings. Open food preferences to see which filters are excluding them.</p>'}</div>${r.recipes.length?btn('Preview these meals','recommend-menu','','primary'):''}<p class="small muted">Applying a preview updates today and future unlogged meals only. Past days and saved meal records are preserved.</p></section>`;}
function chooseRecipes(){const allowed=C.allowedRecipes(state.profile),blocked=state.favorites.filter(id=>!allowed.some(r=>r.id===id));modal(`<h2>Choose your recipes</h2><p>These choices also appear as favorites in your library. Only compatible recipes can be selected.</p><form id="choose-recipes-form">${foodFilterStatus()}${allowed.map(r=>check(r.name,'recipes',state.favorites.includes(r.id),r.id)).join('')||'<p>No compatible recipes. Review food preferences.</p>'}${blocked.length?'<p class="notice">Previously chosen incompatible recipes will remain saved but will not be recommended.</p>':''}<button class="primary" type="submit">Save recipe choices</button></form>`);}
function reviewRecommendedMenu(){const next=C.refreshMeals(state.plan,state.profile,state.favorites,state.mealLogs,today());const days=next.days.filter(d=>d.day>=today());if(!days.length){draft=structuredClone(state.profile);step=5;setup();return;}const cost=C.groceries(next.days.flatMap(d=>d.meals),state.profile,state.extraGroceries).reduce((n,g)=>n+g.purchase,0);modal(`<h2>Your recommended menu</h2><p>Chosen recipes take priority where they fit a meal. Other compatible recipes fill gaps. Existing meal times stay the same; suggested portions use your current profile estimate.</p><p>Estimated grocery purchase: ${money(cost)} / ${money(state.profile.budget)} cap.</p>${cost>state.profile.budget?'<p class="notice danger">This menu exceeds your budget. Review your choices or prices before accepting.</p>':''}${days.map(d=>`<section><h3>${dateLabel(d.day)}</h3>${d.meals.map(m=>`<p>${fmt(m.time)} · ${C.recipe(m.recipe).name} · ${m.servings} portion(s)${state.mealLogs.some(l=>l.id===m.id)?' · already logged, kept':''}</p>`).join('')||'<p>No compatible meals.</p>'}</section>`).join('')}<div class="button-row">${btn('Apply recommended menu','apply-menu','','primary')}${btn('Keep current menu','close','','outline')}</div>`);}

function mealsPage(){if(!state.profile)return setupEmpty();const p=state.profile,all=state.plan.days.flatMap(d=>d.meals),g=C.groceries(all,p,state.extraGroceries),purchase=g.reduce((n,x)=>n+x.purchase,0),consumed=g.reduce((n,x)=>n+x.consumed,0),over=purchase>p.budget;return `${title('MEALS','Meals and grocery plan.','Recipes filtered by your food restrictions, kitchen equipment, prep time, and budget settings.',btn('Edit food preferences','foodfilters','','outline'))}<div class="budget-strip"><div><span class="eyebrow">GROCERIES TO BUY</span><strong>${money(purchase)} <small>/ ${money(p.budget)} cap</small></strong></div><div><span class="eyebrow">PORTIONS CONSUMED</span><strong>${money(consumed)} <small>this week</small></strong></div><div class="${over?'budget-warning':'tag'}">${!all.length?'No menu generated':over?'Over budget by '+money(purchase-p.budget):'Within estimated budget'}</div></div><p class="small muted">Unverified planning prices, not live local prices. Packages purchased and food consumed differ. Pantry stock is deducted from purchases. Update prices in Settings.</p>${over?'<p class="notice danger">This menu exceeds your spending cap. Try economical mode, update pantry stock and actual prices, or change meals. The app will not reduce food portions simply to hide an overrun.</p>':''}${mealRecommendations()}${!day()?`<section class="notice"><p>Your saved menu does not include this waking day. Review a new week to see meals for today.</p>${btn('Review next 7 days','renew','','primary')}</section>`:''}<div class="tabs">${[['plan','7-day menu'],['grocery','Grocery list'],['recipes','Recipe library']].map(([id,t])=>btn(t,'meal-tab',`data-tab="${id}" aria-pressed="${mealTab===id}"`,mealTab===id?'selected':'')).join('')}</div>${mealTab==='plan'?`${week()}${day()?`<div class="section-head"><h2>${dateLabel(day().day)}</h2><span class="muted">${money(day().meals.reduce((a,m)=>a+C.nutrition(C.recipe(m.recipe),m.servings,p).cost,0))} · daily portions</span></div>${day().meals.map((m,i)=>{const r=C.recipe(m.recipe);return `<section class="card menu-card"><div class="recipe-monogram">0${i+1}</div><div><p class="eyebrow">${fmt(m.time)} · ${r.tag}</p><h2>${r.name}</h2><p class="muted">${r.time} min · ${m.servings} portion${m.servings!==1?'s':''} · ${Math.round(C.nutrition(r,m.servings,p).protein)} g protein, est.</p><div class="button-row">${btn('View recipe','recipe',`data-id="${r.id}" data-servings="${m.servings}"`,'outline')}${btn('Swap meal','swap',`data-id="${m.id}"`,'text-btn')}${btn('Time & portion','editmeal',`data-id="${m.id}"`,'text-btn')}</div></div></section>`;}).join('')||'<p class="notice">No compatible menu found. Change your constraints or seek a recipe verified for your restrictions. Unknown allergies pause menu generation.</p>'}`:''}<section class="card"><h3>Batch-cooking note</h3><p class="muted">Adjacent days may reuse recipes and ingredients. Prepare extra portions only when you have reliable cold storage; refrigerate promptly or freeze. Without a fridge, prepare each portion before eating.</p><p class="small muted">Menu totals are calculated estimates. Ingredient nutrition comes from linked USDA records; package labels and cooked yield will differ.</p></section>`:mealTab==='grocery'?`<section class="card"><div class="section-head"><h2>One consolidated list</h2>${btn('Copy list','copygroceries','','outline')}</div><p class="muted">All seven days + recipes you added. Stock quantities are raw edible grams. Package weights should match the edible or drained basis.</p><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>For recipes</th><th>Pantry used</th><th>Buy</th><th>Cost</th></tr></thead><tbody>${!g.length?'<tr><td colspan="5">No grocery items yet. Generate a compatible menu above; the list fills automatically.</td></tr>':''}${g.map(x=>`<tr><td>${x.name}</td><td>${Math.round(x.grams)} g</td><td>${Math.round(x.pantry)} g</td><td>${x.packages} × ${x.pack} g</td><td>${money(x.purchase)}</td></tr>`).join('')}</tbody></table></div>${state.extraGroceries.length?btn('Clear extra recipe additions','clearextra','','text-btn'):''}</section>`:`<div class="recipe-grid">${C.allowedRecipes(p).map(r=>`<section class="card"><div class="section-head"><span class="tag">${r.tag}</span>${state.favorites.includes(r.id)?'<span>★ Saved</span>':''}</div><h2>${r.name}</h2><p class="muted">${r.time} min · ${Math.round(C.nutrition(r).kcal)} kcal · ${money(C.nutrition(r,1,p).cost)} est.</p>${btn('Open recipe '+icon('arrow'),'recipe',`data-id="${r.id}"`,'text-btn')}</section>`).join('')||'<p class="notice">No recipe matches the current restrictions.</p>'}</div>`}`;}
function chart(){const cs=state.checkins.filter(c=>c.weight).slice(-30);if(cs.length<2)return `<div class="empty-chart"><div class="chart-lines"></div><p>${cs.length?'One weigh-in saved. Add another to see your trend.':'Your trend starts with your first check-in.'}</p><span>No sample weights or invented progress.</span></div>`;const vals=cs.map(c=>c.weight),lo=Math.min(...vals)-.5,hi=Math.max(...vals)+.5,coords=vals.map((v,i)=>[40+i*560/(vals.length-1),170-(v-lo)/(hi-lo)*130]);return `<svg class="weight-chart" viewBox="0 0 640 210" role="img" aria-label="Weight chart from ${cs[0].weight} to ${cs.at(-1).weight} kilograms"><path d="M40 40H600M40 105H600M40 170H600" stroke="#e1e5e0" fill="none"/><polyline points="${coords.map(c=>c.join(',')).join(' ')}" stroke="#49745a" stroke-width="3" fill="none"/>${coords.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#49745a"><title>${cs[i].day}: ${vals[i]} kg</title></circle>`).join('')}<text x="40" y="200">${cs[0].day}</text><text x="510" y="200">${cs.at(-1).day}</text><text x="0" y="40">${hi.toFixed(1)}</text><text x="0" y="170">${lo.toFixed(1)}</text></svg>`;}
function progressPage(){if(!state.profile)return setupEmpty();const r=C.weeklyReview(state,today()),xp=C.journey(state).xp;return `${title('PROGRESS','Progress and check-ins.','Review saved sessions, meal logs, weight entries, hunger, and energy.',`<div class="button-row">${btn('TDEE calculator','tdee','','outline')}${btn(icon('plus')+' Check in','checkin','','primary')}</div>`)}<div class="stats"><section class="card"><span class="eyebrow">SESSIONS COMPLETED</span><strong>${state.workouts.length}</strong><p>Every session is saved.</p></section><section class="card"><span class="eyebrow">DAYS WITH A CHECK-IN</span><strong>${state.checkins.length}</strong><p>Weight is always optional.</p></section><section class="card"><span class="eyebrow">${state.profile.journey?'JOURNEY XP':'MEALS LOGGED'}</span><strong>${state.profile.journey?xp:state.mealLogs.length}</strong><p>${state.profile.journey?'Recovery earns progress, too.':'No missing meal counted as zero.'}</p></section></div>${journeyPanel()}<div class="two-grid"><section class="card"><div class="section-head"><h2>Weight over time</h2><span class="tag">kg · optional</span></div>${chart()}<details><summary>View weigh-ins</summary>${state.checkins.filter(c=>c.weight).map(c=>`<p>${c.day} · ${c.weight} kg</p>`).join('')||'<p>No weigh-ins yet.</p>'}</details></section><section class="card"><p class="eyebrow">WEEKLY REVIEW</p><h2>${r.title}</h2><p>${r.text}</p>${r.delta?`<div class="button-row">${btn('Accept +100 kcal','acceptreview','','primary')}${btn('Keep current target','declinereview','','outline')}</div>`:'<span class="tag">No automatic target change</span>'}<p class="small muted">Training: ${state.workouts.filter(w=>w.day>=C.addDays(today(),-6)).length} sessions this week. Food completeness is marked separately in food logging.</p>${state.review.at(-1)?`<p class="small">Last decision: ${esc(state.review.at(-1).decision)} · ${state.review.at(-1).day}</p>`:''}</section></div><section class="card"><div class="section-head"><h2>Training notes</h2><span class="muted">Private journal</span></div><form id="journal-form"><label class="sr-only" for="journal-text">Journal entry</label><textarea id="journal-text" name="text" rows="3" maxlength="10000" required placeholder="Session notes, sleep, pain, schedule changes, or anything to remember"></textarea><div class="form-foot"><span class="small muted">Saved only on this device.</span><button class="primary" type="submit">Save note</button></div></form>${[...state.journal].reverse().slice(0,8).map(j=>`<article class="journal-entry"><span class="eyebrow">${dateLabel(j.day)}</span><p>${esc(j.text)}</p></article>`).join('')}</section>`;}
function settingsPage(){return `${title('SETTINGS','Settings and data.','Manage your schedule, preferences, backups, and calculation sources.')}<div class="settings-grid"><section class="card"><h2>Location & currency</h2><p>${C.cityInfo(region()).name}, ${C.cityInfo(region()).country}<br>${C.cityInfo(region()).zone} · ${region().currency}</p>${btn('Change city & currency','region','','outline')}<h2>Appearance</h2>${select('Color theme','theme',theme,[['system','Follow device'],['light','Light'],['dark','Dark']])}<p class="small muted">Saved on this device. Dark mode also applies to recipes and workout logging.</p></section><section class="card"><h2>Personal plan</h2><p>Schedule, training equipment, food restrictions, nutrition mode, and budget.</p>${btn(state.profile?'Edit setup & review plan':'Set up my plan','setup','','primary')}${state.profile?btn('Suggest my meal & workout times','suggesttiming','','outline'):''}${btn('TDEE calculator','tdee','','outline')}${state.profile?`<div class="settings-summary"><span>${state.profile.nutrition==='habits'?'Habit-only':'Estimated nutrition'} mode</span><span>${money(state.profile.budget)} / week</span><span>${state.profile.minutes}-minute sessions</span></div>`:''}</section><section class="card"><h2>Backup & transfer</h2><p>There is no automatic sync. Export a backup and import it on your other device. A backup contains your personal records; keep it private.</p><div class="button-row">${btn('Export backup','export','','outline')}<label class="button outline">Import backup<input id="import-file" type="file" accept=".json,application/json" hidden></label></div>${storageError?btn('Export unreadable recovery file','recoveryexport','','text-btn'):''}<p class="small muted">Import validates the file, then asks before replacing records. Browser data clearing or storage eviction can remove local records.</p>${btn('Request persistent storage','persist','','text-btn')}</section><section class="card"><h2>Reminders</h2><span class="status-warn">Background push: not connected</span><p>OneSignal offers a free web-push plan, but an account and a secure server-side scheduling connection are not configured. No background push reminders are currently scheduled.</p><p>Calendar alerts are available now. They can fire while this app is closed. Import into a dedicated “Afterhours Fitness” calendar; remove its old events before importing a revised schedule to prevent duplicates.</p>${state.profile?`<div class="button-row">${btn('Reminder settings','reminders','','outline')}${btn('Download calendar alerts','calendar','','primary')}</div>`:''}<div class="button-row">${btn('Test device notification','testnotification','','text-btn')}</div><p class="small muted" id="notification-status">Permission: ${'Notification'in window?Notification.permission:'unavailable in this browser'}. The test is immediate, not a scheduled background-delivery test. iPhone web notifications require installation on the Home Screen. Internet, browser permission, and Focus settings affect push delivery; timing is not guaranteed.</p></section><section class="card"><h2>Install Afterhours Fitness</h2><ol><li><strong>iPhone:</strong> Open the hosted link in Safari. Open Share, choose Add to Home Screen, then Add.</li><li><strong>Mac:</strong> Open the link in Safari. Choose File → Add to Dock.</li><li>Open once while online to cache the app. Check offline access before relying on it.</li></ol><p class="small muted">${'serviceWorker'in navigator?'Offline cache supported in this browser.':'Offline cache unavailable in this browser.'} <span id="offline-status"></span></p></section></div>${state.profile?`<section class="card"><div class="section-head"><h2>Pantry & local prices</h2><span class="tag">${region().currency} · grams</span></div><p class="muted">Starting prices are illustrative placeholders, not verified market quotes. Enter the package price and edible/drained package size from your receipt. Pantry stock reduces the grocery list.</p><form id="prices-form"><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Pantry g</th><th>Package g</th><th>Package ${region().currency}</th><th>Source / date</th></tr></thead><tbody>${Object.entries(ingredients).map(([id,i])=>{const pr=state.profile.prices[id];return `<tr><td>${i.name}</td><td><input aria-label="${i.name} pantry grams" name="pantry-${id}" type="number" min="0" max="100000" value="${state.profile.pantry[id]||0}"></td><td><input aria-label="${i.name} package grams" name="pack-${id}" type="number" min="1" max="100000" value="${pr?.pack||i.pack}"></td><td><input aria-label="${i.name} package ${region().currency}" name="price-${id}" type="number" min="0" max="${amount(100000)}" step="any" value="${amount(pr?.price??i.price)}"></td><td><input aria-label="${i.name} price source" name="source-${id}" value="${esc(pr?.source||'Unverified planning estimate')}"><small>${pr?.date||'No observed date'}</small></td></tr>`;}).join('')}</tbody></table></div><button class="primary" type="submit">Save stock & prices</button></form></section>`:''}${methodSummary()}<details class="card"><summary>Methods, sources, and limitations</summary><p>All times use ${C.cityInfo(region()).zone}. A waking day begins at your chosen wake time. Overnight meals belong to that day. Workouts use three suggested nonconsecutive days and your verified equipment; the same session moves to 02:30 when it does not fit before work. Recovery days are intentional.</p><p>Optional adult energy estimate: Mifflin–St Jeor resting energy = 10 × kg + 6.25 × cm − 5 × age + sex coefficient (+5 or −161), multiplied by your selected activity factor. Fat-loss preference uses a modest 10% starting reduction. Protein reference: 1.6 g/kg. These are rough starting estimates, not measured needs; no automatic calorie cuts.</p><p>Energy and protein inputs are extracted from official USDA SR Legacy food records, with record links and proxy warnings in every recipe. Recipe totals are calculated estimates. Direct Philippine nutrient records were not available for verified extraction from PhilFCT. Prices are placeholders. Check product labels for allergens and cross-contact; the app cannot verify brands. Unknown allergy notes pause menu generation.</p><p>App files and bundled recipes can be exposed through hosting; personal records are never embedded in published files. No analytics, paid API, or subscription is required by the app. Free hosting and push providers may change their terms or availability. This build has no active push service.</p><ul>${sources.map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noreferrer">${t}</a></li>`).join('')}</ul><p class="small muted">References checked September 22, 2026. Personal medical needs, pregnancy, eating-disorder recovery, or other clinical nutrition concerns require individualized care; habit-only mode avoids numerical targets.</p></details><section class="card danger-zone"><h3>Delete local records</h3><p>This affects this browser only. Export first if you want to keep a copy.</p>${btn('Delete my data','delete','','danger-button')}</section>`;}
function render(){if(!['today','training','meals','progress','settings'].includes(view))view='today';$('#app').innerHTML=shell(({today:todayPage,training:trainingPage,meals:mealsPage,progress:progressPage,settings:settingsPage}[view])());}
function setup(){const p=draft,days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const contents=[
`<p class="muted">Choose a starting point. These preferences stay on this device, and you can change them later.</p><div class="form-grid">${select('Your main priority','goal',p.goal,['consistency','fat loss','build muscle'])}${select('Training experience','experience',p.experience,['beginner','returning','experienced'])}${select('Session length','minutes',p.minutes,[[20,'20 minutes'],[35,'35 minutes'],[45,'45 minutes'],[60,'60 minutes']])}${select('Nutrition approach','nutrition',p.nutrition,[['habits','Habits only — no measurements'],['estimates','Optional calorie & protein estimates']])}</div><details ${p.nutrition==='estimates'?'open':''}><summary>Optional personal measurements</summary><p class="small muted">Age, weight, height, and an equation coefficient help estimate adult energy needs. They are optional; leaving them blank keeps you in habit-only planning. This equation is not a measurement of your metabolism.</p><div class="form-grid">${field('Age (18+ for estimates)','age',p.age,'number','min="18" max="100"')}${field('Weight (kg)','weight',p.weight,'number','min="30" max="300" step=".1"')}${field('Height (cm)','height',p.height,'number','min="120" max="230"')}${select('Equation coefficient','sex',p.sex,[['','Do not estimate'],['female','Female coefficient (−161)'],['male','Male coefficient (+5)']])}${select('Activity outside workouts','activity',p.activity,[[1.2,'Mostly sitting'],[1.4,'Lightly active'],[1.6,'Moderately active']])}</div></details><div id="setup-tdee-result" aria-live="polite">${p.nutrition==='estimates'?tdeeResult(p):''}</div>${check('Use the optional 66-day journey and XP','journey',p.journey)}`,
`<p class="muted">Enter when you wake, work, and sleep. Let Afterhours suggest when to eat and train, or choose your own times. All times use ${C.cityInfo(region()).zone}. Change location from Settings or the city button in the header.</p>${select('How should we choose meal and workout times?','timingMode',p.timingMode||'manual',[['suggested','Suggest times from my schedule'],['manual','Keep my own times']])}<label>Workdays (day your shift starts)</label><div class="daychecks">${days.map((d,i)=>check(d,'workdays',p.workdays.includes(i),i)).join('')}</div><div class="form-grid">${field('Wake on workdays','wake',p.wake,'time','required')}${field('Sleep on workdays','sleep',p.sleep,'time','required')}${field('Shift starts','workStart',p.workStart,'time','required')}${field('Shift ends','workEnd',p.workEnd,'time','required')}${field('Preparation before work (minutes)','prep',p.prep,'number','min="0" max="180" required')}${field('Workday workout (used in manual mode)','workout',p.workout,'time','required')}${field('Wake on days off','offWake',p.offWake,'time','required')}${field('Sleep on days off','offSleep',p.offSleep,'time','required')}${field('Day-off workout (used in manual mode)','offWorkout',p.offWorkout,'time','required')}</div><label>Strength days</label><div class="daychecks">${days.map((d,i)=>check(d,'trainDays',p.trainDays.includes(i),i)).join('')}</div><p class="small muted">Choose 2–3 nonconsecutive days to leave recovery time. If the preferred session cannot fit, the same session moves to 02:30.</p>`,
`<p class="muted">Confirm what you can safely use. No equipment is assumed until you select it.</p>${check('I have dumbbells','dumbbell',p.equipment.includes('dumbbell'))}<div class="form-grid">${select('Bench type','bench',p.bench,[['none','No confirmed bench'],['flat','Stable flat bench'],['adjustable','Stable adjustable bench']])}${select('Barbell available?','barbell',p.barbell?'yes':'no',[['no','No / not confirmed'],['yes','Yes']])}${field('Available dumbbell weights (kg, per dumbbell)','weights',p.weights,'text','placeholder="e.g. 2, 4, 6, 8, 10"')}${field('Smallest weight increase (kg)','increment',p.increment,'number','min=".25" max="20" step=".25" required')}</div><p class="small muted">Barbell availability is recorded, but barbell bench pressing is excluded until rack and safety support can be verified. Bodyweight movements remain available.</p><label>Movement limitations to avoid</label><div class="check-grid">${['knee','back','shoulder','wrist'].map(l=>check(l[0].toUpperCase()+l.slice(1),'limitations',p.limitations.includes(l),l)).join('')}</div>${field('Other limitations (optional)','otherLimit',p.otherLimit,'text','maxlength="500"')}<p class="small muted">A written limitation pauses automatic exercise selection because it needs individual review. Never train through pain.</p>`,
`<div class="form-grid">${field('Weekly grocery cap ('+region().currency+')','budget',amount(p.budget),'number',`min="0" max="${amount(100000)}" step="any" required`)}${select('Menu approach','style',p.style,[['economical','Economical · lowest-cost rotation'],['balanced','Balanced cost · more variety'],['convenience','Convenience · faster preparation']])}${select('Food preference','diet',p.diet,[['any','No dietary preference'],['vegetarian','Vegetarian (eggs allowed)']])}${field('Maximum recipe time (minutes)','prepTime',p.prepTime,'number','min="5" max="180" required')}</div><label><strong>Foods to EXCLUDE</strong> — leave unchecked if you eat them</label><p class="small muted">Checking a food removes recipes containing it. These are not foods you want included.</p><div class="check-grid">${['egg','soy','fish','gluten','legume','milk','peanut','tree nut','shellfish','sesame'].map(a=>check(a,'allergies',p.allergies.includes(a),a)).join('')}</div>${field('Other allergies (unrecognized terms pause menus)','otherAllergy',p.otherAllergy,'text','maxlength="500"')}${field('Ingredients to avoid (comma-separated names)','avoid',p.avoid,'text','placeholder="e.g. banana, sardine" maxlength="500"')}<label>Cooking and storage equipment</label><div class="check-grid">${['stove','rice cooker','microwave','fridge'].map(k=>check(k,'kitchen',p.kitchen.includes(k),k)).join('')}</div><details><summary>Pantry stock I already have</summary><div class="form-grid">${Object.entries(ingredients).map(([id,i])=>field(i.name+' (raw edible g)','stock-'+id,p.pantry[id]||0,'number','min="0" max="100000"')).join('')}</div></details>`,
`<p class="muted">${p.timingMode==='suggested'?'These meal times were suggested from your wake time, work shift, and sleep window.':'These are your saved meal times.'} Confirm that your work breaks allow them, or edit any time. After-midnight meals stay with the same waking day.</p><div class="form-grid">${p.meals.map((t,i)=>field('Workday meal '+(i+1),'meal'+i,t,'time','required')).join('')}${p.offMeals.map((t,i)=>field('Day-off meal '+(i+1),'offmeal'+i,t,'time','required')).join('')}</div><h3>Quiet hours</h3><div class="form-grid">${field('Silence from','quietStart',p.quietStart,'time','required')}${field('Until','quietEnd',p.quietEnd,'time','required')}</div><p class="small muted">Reminders during quiet hours or your sleep window are omitted. Scheduled background push is not connected; downloadable calendar alerts are available after setup.</p>`
];if(step===5){const preview=C.buildPlan(p,C.wakingDay(p),state.plan,state.workouts,state.favorites),g=C.groceries(preview.days.flatMap(d=>d.meals),p),cost=g.reduce((a,x)=>a+x.purchase,0),r=C.routine(p);modal(`<p class="eyebrow">STEP 6 OF 6 · YOUR PLAN</p><h2>Make it your own.</h2><p class="muted">Nothing starts until you accept. Use Back to change your preferences.</p><div class="review-summary"><div><span>Training</span><strong>${p.trainDays.length} days · ${r.length} movements · ${p.minutes} min</strong></div><div><span>Nutrition</span><strong>${preview.targets?`${preview.targets.kcal} kcal · ${preview.targets.protein} g protein (est.)`:'Habit-only · no numerical targets'}</strong></div><div><span>Groceries to buy</span><strong>${money(cost)} / ${money(p.budget)} estimated cap</strong></div></div>${cost>p.budget?`<p class="notice danger">Menu exceeds your cap by ${money(cost-p.budget)}. It is not a budget-feasible plan yet.</p>`:''}${!C.allowedRecipes(p).length?'<p class="notice danger">No recipes meet all restrictions. Your meal plan will remain empty until constraints are reviewed.</p>':''}${!r.length?'<p class="notice danger">Automatic exercise selection is paused. Review movement limitations.</p>':''}<div class="review-days">${preview.days.map(d=>`<div><strong>${dateLabel(d.day)}</strong><span>${d.scheduleWarning|| (d.workout?'Train '+fmt(d.workout.time)+' · '+d.workout.duration+' min':'Recovery')}</span><small>${d.meals.map(m=>fmt(m.time)).join(' / ')}</small></div>`).join('')}</div><p class="small muted">Meal estimates may not meet your exact targets. Portions are adjusted in quarter-serving steps, with a cap of 2.5 servings. Review meals after starting. Completed history is preserved when plans change.</p><div class="form-foot">${btn('Back','setup-back','','outline')}${btn('Accept & save my plan','acceptplan','','primary')}</div>`);return;}
modal(`<p class="eyebrow">STEP ${step+1} OF 6 · ${['STARTING POINT','YOUR SCHEDULE','YOUR EQUIPMENT','FOOD & BUDGET','MEAL BREAKS'][step]}</p><div class="step-progress">${Array.from({length:6},(_,i)=>`<i class="${i<=step?'filled':''}"></i>`).join('')}</div><h2>${['Let’s find your starting point.','Work with your body clock.','Your own training room.','Food that works for you.','A place for every meal.'][step]}</h2><form id="setup-form">${contents[step]}<p id="setup-error" class="error" role="alert"></p><div class="form-foot">${step?btn('Back','setup-back','','outline'):'<span class="small muted">Private · local to this device</span>'}<button class="primary" type="submit">${step===4?'Review my plan':'Continue'} ${icon('arrow')}</button></div></form>`);}
function readSetup(form){const f=new FormData(form),p=draft,get=n=>f.get(n),all=n=>f.getAll(n);if(step===0){for(const n of ['goal','experience','nutrition','sex'])p[n]=get(n);for(const n of ['minutes','activity'])p[n]=Number(get(n));for(const n of ['age','height','weight'])p[n]=get(n)?Number(get(n)):null;p.journey=f.has('journey');}
if(step===1){p.timingMode=get('timingMode');for(const n of ['wake','sleep','offWake','offSleep','workStart','workEnd','workout','offWorkout'])p[n]=get(n);p.prep=Number(get('prep'));p.workdays=all('workdays').map(Number);p.trainDays=all('trainDays').map(Number);if(p.trainDays.length>3||p.trainDays.some(d=>p.trainDays.includes((d+1)%7)))throw Error('Choose up to 3 strength days with a recovery day between sessions.');if(p.wake===p.sleep||p.offWake===p.offSleep)throw Error('Wake and sleep times must differ.');if(p.timingMode==='suggested')Object.assign(p,C.applySuggestedTiming(p));}
if(step===2){p.equipment=f.has('dumbbell')?['dumbbell']:[];p.bench=get('bench');p.barbell=get('barbell')==='yes';p.weights=get('weights');p.increment=Number(get('increment'));p.limitations=all('limitations');p.otherLimit=get('otherLimit').trim();if(p.equipment.includes('dumbbell')&&(!p.weights.trim()||p.weights.split(',').some(x=>!Number(x)||Number(x)<0||Number(x)>200)))throw Error('List your available dumbbell weights as positive kg values separated by commas.');}
if(step===3){p.budget=Number(get('budget'))===amount(p.budget)?p.budget:baseAmount(get('budget'));p.style=get('style');p.diet=get('diet');p.prepTime=Number(get('prepTime'));p.allergies=all('allergies');p.kitchen=all('kitchen');p.otherAllergy=get('otherAllergy').trim();p.avoid=get('avoid');for(const id of Object.keys(ingredients))p.pantry[id]=Number(get('stock-'+id));}
if(step===4){p.meals=[0,1,2].map(i=>get('meal'+i));p.offMeals=[0,1,2].map(i=>get('offmeal'+i));p.quietStart=get('quietStart');p.quietEnd=get('quietEnd');for(const [ts,s]of [[p.meals,{wake:p.wake,sleep:p.sleep}],[p.offMeals,{wake:p.offWake,sleep:p.offSleep}]])if(ts.some(t=>C.isAsleep(t,s)))throw Error('A meal falls inside your sleep window. Choose a time while awake or edit your schedule.');}}
function showRecipe(id,n=1){activeRecipe=C.recipe(id);recipeServings=n;const r=activeRecipe,p=state.profile||C.defaults,t=C.nutrition(r,n,p);modal(`<p class="eyebrow">${r.tag} · ${r.prep} MIN PREP / ${r.cook} MIN COOK</p><h2>${r.name}</h2><div class="recipe-tools"><label>Servings<input id="recipe-servings" type="number" min=".25" max="10" step=".25" value="${n}"></label><span>${Math.round(t.kcal)} kcal · ${Math.round(t.protein)} g protein<br>${money(t.cost)} total · estimates</span></div><h3>What you’ll need</h3><p class="small muted">Raw edible grams unless labeled. Rice and mung beans are dry weights; canned tuna is drained. Household measures are approximate and scale with the recipe.</p><ul class="ingredients">${Object.entries(r.items).map(([id,g])=>`<li><strong>${+(g*n).toFixed(1)} g</strong><span>${ingredients[id].name}<small>${C.household(id,g*n)}</small></span></li>`).join('')}</ul><p class="small muted">Water as directed; optional pinch of salt. When batch cooking, use enough water for the scaled grains and keep the stew consistency similar.</p>${cookingGuide(r)}${foodEvidence(r)}<h3>Let’s cook</h3><ol class="steps">${C.scaledSteps(r,n).map(s=>`<li>${s}</li>`).join('')}</ol><h3>Substitutions</h3><p>${r.subs} Use a meal swap for recalculated totals; informal substitutions change estimates.</p><h3>Keep it safely</h3><p>${r.storage}</p><p class="small muted">Per standard serving: ${Math.round(C.nutrition(r,1,p).kcal)} kcal · ${Math.round(C.nutrition(r,1,p).protein)} g protein · ${money(C.nutrition(r,1,p).cost)}. Nutrition and prices are estimates.</p><div class="button-row">${btn('Copy complete recipe','copyrecipe','','primary')}${btn(state.favorites.includes(id)?'★ Saved':'☆ Save favorite','favorite',`data-id="${id}"`,'outline')}${btn('Add to grocery list','addgrocery',`data-id="${id}"`,'outline')}</div>`);}

function journeyPanel(){if(!state.profile.journey)return '';const j=C.journey(state);return `<section class="card rank-card"><p class="eyebrow">YOUR TRAINING JOURNEY</p><h2>${j.rank}</h2><strong>${j.xp} XP</strong><div class="bar" role="progressbar" aria-label="Rank progress" aria-valuenow="${Math.round(j.percent)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${j.percent}%"></span></div><p>${j.next?j.remaining+' XP to '+j.next:'Challenger reached. Keep enjoying your routine.'}</p><details><summary>Ranks & XP rules</summary><p>20 XP per exercise with a saved set, once per waking day; 30 XP per saved session; 10 XP per planned meal and daily essential. Every 250 XP advances one division. Extra reps, heavier weights, and skipped food earn no extra XP. Rest days never deduct XP; correcting or undoing a record recalculates rewards.</p><p>${C.rankLadder.join(' → ')}</p><p>Rank names follow <a href="https://support.riotgames.com/en-us/league-of-legends/gameplay/ranked-tiers-divisions-and-queues" target="_blank" rel="noopener noreferrer">League of Legends tiers</a>. This is an independent fitness ladder with its own XP rules, not a Riot product or a measure of athletic ability.</p></details><h3>Achievements</h3><div class="achievement-grid">${j.achievements.map(a=>`<article class="achievement ${a.unlocked?'unlocked':'locked'}"><span class="tag">${a.unlocked?'✓ Unlocked':'Locked'}</span><h3>${a.name}</h3><p>${a.rule}</p><small>${Math.min(a.value,a.target)} / ${a.target}</small></article>`).join('')}</div></section>`;}
function readiness(){if(session&&session.day===day()?.day)return startWorkout();modal(`<p class="eyebrow">TODAY’S COACH CHECK-IN</p><h2>How are you feeling?</h2><p>Choose the session that fits your energy. Start with five minutes of easy movement and gentle practice reps. Aim for controlled repetitions with a little effort left.</p><div class="button-row">${btn('Ready for my session','ready','','primary')}${btn('Tired — lighter session','ready-light','','outline')}${btn('Take a recovery day','ready-recovery','','outline')}</div><p class="small muted">If you feel unwell, dizzy, or have new pain, pause training. The app cannot assess symptoms or see your technique. Use the demonstration and stop movements that hurt.</p>`);}

function startWorkout(){const d=day();if(!d?.workout)return toast('Choose a strength day first.');if(doneWorkout(d.day))return history(d.day);const es=C.routine(state.profile,d.workout.light||d.workout.duration<25);if(!es.length)return toast('No compatible exercises. Review your limitations in Settings.');if(!session||session.day!==d.day)session={day:d.day,exercises:es.map(e=>({id:e.id,formQuality:'',sets:Array.from({length:e.sets},()=>({reps:e.reps[0],weight:e.unit==='bodyweight'?0:C.progression(state.workouts,e,state.profile).weight,rpe:7}))}))};drawSession();}
function drawSession(){modal(`<p class="eyebrow">SESSION · ${dateLabel(session.day)}</p><h2>One set at a time.</h2><p class="muted">Warm up for 5 minutes with easy movement and practice reps. Effort 7–8 means roughly 2–3 good reps left. Save only sets you complete.</p><form id="workout-form">${session.exercises.map((entry,i)=>{const e=exercises.find(e=>e.id===entry.id),prog=C.progression(state.workouts,e,state.profile),prev=C.previousPerformance(state.workouts,e.id),alts=C.availableExercises(state.profile).filter(a=>a.pattern===e.pattern);return `<section class="session-exercise"><div class="section-head"><h3>${e.name}</h3><select aria-label="Substitute ${e.name}" data-substitute="${i}">${alts.map(a=>`<option value="${a.id}" ${a.id===e.id?'selected':''}>${a.name}</option>`).join('')}</select></div><p class="small">${e.cues}</p>${formVideo(e)}${select('How did your technique feel?','form-'+i,entry.formQuality||'',[['','Not recorded — hold progression'],['controlled','Controlled throughout'],['uncertain','Unsure — review demonstration'],['broke-down','Lost control — reduce difficulty']])}<p class="small muted">Self-report only. The app cannot observe or verify your form.</p><p class="small muted">${e.reps.join('–')} reps · ${e.rest}s rest · weight ${e.unit}.<br>${prog.note}</p><p class="small">Previous: ${prev?prev.sets.map(s=>s.reps+' × '+s.weight+' kg').join(' / '):'No saved sets yet'}</p><div class="set-row set-heading"><span>Set</span><span>Reps</span><span>kg</span><span>Effort /10</span><span>Done</span></div>${entry.sets.map((s,j)=>`<div class="set-row"><span>${j+1}</span><input aria-label="${e.name} set ${j+1} reps" name="reps-${i}-${j}" type="number" min="1" max="100" required value="${s.reps}"><input aria-label="${e.name} set ${j+1} kg" name="weight-${i}-${j}" type="number" min="0" max="500" step=".25" required value="${s.weight}" ${e.unit==='bodyweight'?'readonly':''}><input aria-label="${e.name} set ${j+1} effort" name="rpe-${i}-${j}" type="number" min="1" max="10" required value="${s.rpe}"><input aria-label="${e.name} set ${j+1} completed" name="done-${i}-${j}" type="checkbox" ${s.done?'checked':''}></div>`).join('')}</section>`;}).join('')}<p class="small muted">You can finish early. Only checked sets are recorded. Completed history is never rewritten by plan edits.</p><button class="primary full" type="submit">Finish & save completed sets</button></form>`);}
function captureSession(){const f=new FormData($('#workout-form'));session.exercises.forEach((e,i)=>{e.formQuality=f.get('form-'+i)||'';e.sets.forEach((s,j)=>{s.reps=Number(f.get(`reps-${i}-${j}`));s.weight=Number(f.get(`weight-${i}-${j}`));s.rpe=Number(f.get(`rpe-${i}-${j}`));s.done=f.has(`done-${i}-${j}`);});});}
function history(d){const w=doneWorkout(d);if(!w)return;modal(`<p class="eyebrow">COMPLETED · ${dateLabel(d)}</p><h2>Your session, saved.</h2>${w.exercises.map(entry=>`<section class="session-exercise"><h3>${exercises.find(e=>e.id===entry.id).name}</h3><p class="small muted">Technique self-report: ${esc(entry.formQuality||'not recorded')}</p>${entry.sets.map((s,i)=>`<p>Set ${i+1} · ${s.reps} reps × ${s.weight} kg · effort ${s.rpe}/10</p>`).join('')}</section>`).join('')}<p class="small muted">Recorded ${new Date(w.saved).toLocaleString()}. Changes to your plan will not change this record.</p>`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{modal(`<h2>Copy this text</h2><p>Clipboard access is unavailable here. Select the text to copy it.</p><textarea rows="15" readonly>${esc(text)}</textarea>`);$('#modal textarea').select();}}
function download(text,name,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function checkin(){const d=selectedDay||today(),c=state.checkins.find(c=>c.day===d);modal(`<p class="eyebrow">WAKING DAY · ${dateLabel(d)}</p><h2>How are you doing?</h2><form id="checkin-form">${field('Day','day',d,'date','required')}${field('Weight in kg (optional)','weight',c?.weight||'','number','min="20" max="400" step=".1"')}<p class="small muted">If weighing, use similar conditions after waking. One reading is not a trend.</p><div class="form-grid">${select('Hunger','hunger',c?.hunger||3,[[1,'1 · Low'],[2,'2 · Mild'],[3,'3 · Manageable'],[4,'4 · Often hungry'],[5,'5 · Very hungry']])}${select('Energy','energy',c?.energy||3,[[1,'1 · Very low'],[2,'2 · Low'],[3,'3 · Okay'],[4,'4 · Good'],[5,'5 · High']])}</div><button class="primary" type="submit">Save check-in</button></form>`);}
function reminderSettings(){const p=state.profile;modal(`<h2>Your reminder preferences</h2><form id="reminder-form">${check('Workout alerts','workout',p.reminders.workout)}${p.reminders.meals.map((v,i)=>check('Meal '+(i+1)+' alerts','meal'+i,v)).join('')}<div class="form-grid">${field('Quiet hours start','quietStart',p.quietStart,'time','required')}${field('Quiet hours end','quietEnd',p.quietEnd,'time','required')}</div><p class="muted">Sleep and quiet hours suppress calendar events. After any schedule edit, replace the previous Afterhours calendar events with a fresh export. Imported events cannot be remotely changed by this local app.</p><button type="submit" class="primary">Save preferences</button></form>`);}
function regionDialog(){const r=region(),city=C.cityInfo(r);modal(`<h2>Location & currency</h2><form id="region-form"><div class="form-grid">${select('Country','country',city.country,['Philippines','Australia','Singapore'])}<div id="region-cities">${cityOptions(city.country,r.city)}</div>${select('Currency','currency',r.currency,[['PHP','PHP · Philippine peso'],['USD','USD · US dollar'],['SGD','SGD · Singapore dollar'],['AUD','AUD · Australian dollar']])}<div id="region-rate">${rateField(r.currency,r.rate)}</div></div><p id="region-zone" class="notice">Schedule time zone: ${city.zone}</p><p class="small muted">Singapore is a city-state; its listed towns and areas all use Singapore time. Australian daylight saving adjusts automatically where observed.</p><p>Meal, work, and workout hours stay the same on the local clock in your chosen city. Saved history stays unchanged. Replace previously imported calendar alerts after changing city. During daylight saving transitions, a missing time moves forward by the clock change; a repeated time uses its first occurrence.</p><p class="small muted">Currency conversion uses your entered planning rate, not a live exchange rate. For example, if 1 dollar costs 50 pesos, enter 0.02 (1 ÷ 50). Existing budgets and prices retain their value; enter local shop prices in Settings. Currency conversion does not estimate prices in another country.</p><button class="primary" type="submit">Save location & currency</button></form>`);}
function cityOptions(country,id){return select('City / area','city',id,C.cities.filter(c=>c.country===country).map(c=>[c.id,c.name]));}
function rateField(currency,rate){return currency==='PHP'?'<p>Base currency: Philippine peso (PHP).</p>':field('1 PHP equals how many '+currency+'?','rate',rate||'','number','min="0.000001" max="10000" step="any" required placeholder="Enter your planning exchange rate"');}
async function action(el){const a=el.dataset.action,id=el.dataset.id,d=el.dataset.day;
if(a==='updateapp'&&waitingUpdate){waitingUpdate.postMessage({type:'ACTIVATE_UPDATE'});return;}
if(a==='region'){regionDialog();return;}
if(a==='close'){if($('#workout-form'))captureSession();close();}
if(a==='undo'&&undoState){const old=state;state=undoState;try{localStorage.setItem(KEY,JSON.stringify(state));undoState=old;render();toast('Change undone.');}catch{state=old;toast('Could not save undo.');}}
if(a==='setup'){draft=structuredClone(state.profile||C.defaults);draft.city=region().city;draft.timingMode||='manual';step=0;setup();}
if(a==='setup-back'){if($('#setup-form')){try{readSetup($('#setup-form'));}catch{}}step--;setup();}
if(a==='acceptplan'){if(save('Plan saved. Your history is preserved.',()=>{const old=state.plan;state.profile=structuredClone(draft);state.plan=C.buildPlan(state.profile,C.wakingDay(state.profile),old,state.workouts,state.favorites);selectedDay=state.plan.start;session=null;})){close();view='today';location.hash='today';render();}}
if(a==='suggesttiming'){const p=state.profile,t=C.suggestTiming(p);modal(`<p class="eyebrow">BASED ON YOUR SAVED SCHEDULE</p><h2>Here’s a rhythm to try.</h2><p>Food choices still follow your budget, pantry, and restrictions. These suggestions change timing only.</p>${[['Workdays',t.work,p.wake,p.sleep],['Days off',t.off,p.offWake,p.offSleep]].map(([name,s,wake,sleep])=>`<section class="card"><h3>${name}</h3><p class="small muted">Wake ${fmt(wake)} · Sleep ${fmt(sleep)}${name==='Workdays'?' · Work '+fmt(p.workStart)+'–'+fmt(p.workEnd):''}</p><p><strong>Workout:</strong> ${s.workout?fmt(s.workout.time)+' · '+s.workout.duration+' min':'No suitable window — review your schedule'}</p><p><strong>Meals:</strong> ${s.meals.map(fmt).join(' · ')}</p>${s.reasons.map(r=>`<p class="small muted">${r}</p>`).join('')}</section>`).join('')}<p class="small muted">You can edit any time afterward. Completed workouts and meals stay unchanged. If you imported calendar alerts, replace those events after accepting.</p><div class="button-row">${btn('Use these times','accepttiming','','primary')}${btn('Keep current times','close','','outline')}</div>`);}
if(a==='accepttiming'){if(save('Suggested times saved. Completed records are unchanged.',()=>{state.profile=C.applySuggestedTiming(state.profile);for(const d of state.plan.days){const settings=C.settingsFor(state.profile,d.day);d.meals.forEach((m,i)=>{if(!state.mealLogs.some(l=>l.id===m.id))m.time=settings.meals[i];});if(state.profile.trainDays.includes(C.weekday(d.day))&&!doneWorkout(d.day)){const w=C.workoutTime(state.profile,d.day);if(w){d.workout={id:`workout-${d.day}`,light:false,...d.workout,...w};d.scheduleWarning=null;}else{d.scheduleWarning='No workout fits your waking hours. Review your schedule.';d.workout=null;}}}session=null;}))close();}
if(a==='renew'){draft=structuredClone(state.profile);step=5;setup();}
if(a==='day'){selectedDay=d;render();}
if(a==='habit'||a==='recovery'){const dd=d||selectedDay||today();save('Daily essential updated.',()=>{state.habits[dd]||={};const key=a==='recovery'?'recovery':id;state.habits[dd][key]=!state.habits[dd][key];});}
if(a==='recipe')showRecipe(id,Number(el.dataset.servings)||1);
if(a==='favorite'){save('Favorite updated.',()=>{state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];});showRecipe(id,recipeServings);}
if(a==='copyrecipe')await copy(C.recipeText(activeRecipe,recipeServings,state.profile||C.defaults,region()));
if(a==='addgrocery'){save('Recipe quantities added to the grocery list.',()=>state.extraGroceries.push({recipe:id,servings:recipeServings}));}
if(a==='clearextra')save('Extra grocery additions cleared.',()=>state.extraGroceries=[]);
if(a==='foodfilters')foodFilters();
if(a==='choose-recipes')chooseRecipes();
if(a==='recommend-menu')reviewRecommendedMenu();
if(a==='apply-menu'){if(save('Recommended menu saved. Groceries updated; replace imported calendar alerts.',()=>{state.plan=C.refreshMeals(state.plan,state.profile,state.favorites,state.mealLogs,today());mealTab='plan';selectedDay=state.plan.days.some(d=>d.day===today())?today():state.plan.start;}))close();}
if(a==='meal-tab'){mealTab=el.dataset.tab;render();}
if(a==='logmeal'){const m=state.plan.days.flatMap(d=>d.meals).find(m=>m.id===id);save('Meal log updated.',()=>{state.mealLogs=state.mealLogs.some(l=>l.id===id)?state.mealLogs.filter(l=>l.id!==id):[...state.mealLogs,{...m,day:d,nutrition:C.nutrition(C.recipe(m.recipe),m.servings,state.profile)}];});}
if(a==='swap'){const m=state.plan.days.flatMap(d=>d.meals).find(m=>m.id===id);modal(`<h2>Swap your meal</h2><p>Only recipes matching your allergies, preferences, kitchen, and prep time appear. Existing food logs keep their original nutrition.</p><form id="swap-form" data-id="${id}">${select('Recipe','recipe',m.recipe,C.allowedRecipes(state.profile).map(r=>[r.id,r.name]))}<button class="primary" type="submit">Save meal swap</button></form>`);}
if(a==='editmeal'){const m=state.plan.days.flatMap(d=>d.meals).find(m=>m.id===id);modal(`<h2>Meal time & portion</h2><form id="editmeal-form" data-id="${id}">${field('Time ('+C.cityInfo(region()).zone+')','time',m.time,'time','required')}${field('Portions of the standard recipe','servings',m.servings,'number','min=".25" max="10" step=".25" required')}<p class="small muted">Nutrition, grocery quantities, and costs update together. Replace previously imported calendar alerts after changing times.</p><button class="primary" type="submit">Save changes</button></form>`);}
if(a==='reschedule'){const dd=state.plan.days.find(x=>x.day===(d||selectedDay||today()));modal(`<h2>Move this session</h2><p>This changes the existing workout, without creating another one. Overnight times stay with ${dateLabel(dd.day)}.</p><form id="reschedule-form" data-day="${dd.day}">${field('Workout time','time',dd.workout.time,'time','required')}<div class="button-row">${btn('02:30 backup','picktime','data-time="02:30"','outline')}${btn('09:30 after work','picktime','data-time="09:30"','outline')}</div><p class="small muted">Choose after-work training only when it suits your energy and sleep. Calendar alerts need a fresh export after edits.</p><button class="primary" type="submit">Move session</button></form>`);}
if(a==='picktime')$('#reschedule-form input').value=el.dataset.time;
if(a==='start')readiness();
if(a==='ready'){close();startWorkout();}
if(a==='ready-light'){if(save('Lighter session selected.',()=>{day().workout.light=true;session=null;})){close();startWorkout();}}
if(a==='ready-recovery'){if(save('Recovery day saved. Replace calendar alerts after changing the plan.',()=>{const d=day();state.habits[d.day]||={};state.habits[d.day].recovery=true;d.workout=null;session=null;}))close();}
if(a==='light'){save('Session intensity updated.',()=>{day().workout.light=!day().workout.light;session=null;});}
if(a==='history')history(d||selectedDay||today());
if(a==='checkin')checkin();
if(a==='tdee')openTDEE();
if(a==='food'){const dd=selectedDay||today(),f=state.foodLogs.find(l=>l.day===dd);modal(`<h2>Daily food record</h2><p>Enter the complete day's total from your own tracking, including logged planned meals. This record is separate from meal checkmarks, so it is never added twice.</p><form id="food-form">${field('Waking day','day',dd,'date','required')}${field('Total energy (kcal)','kcal',f?.kcal??'','number','min="0" max="20000" required')}${field('Total protein (g)','protein',f?.protein??'','number','min="0" max="1000" step=".1" required')}${check('This includes everything I ate in this waking day','complete',f?.complete)}<p class="small muted">Unchecked means partial, not zero. Weekly review requires enough complete days.</p><button class="primary" type="submit">Save food record</button></form>`);}
if(a==='acceptreview'||a==='declinereview'){const r=C.weeklyReview(state,today());if(a==='acceptreview'&&!r.delta)return;save('Review decision saved.',()=>{if(a==='acceptreview')state.plan.targets.kcal+=r.delta;state.review.push({day:today(),decision:a==='acceptreview'?'Accepted +100 kcal':'Kept targets unchanged'});});}
if(a==='export')download(JSON.stringify(state,null,2),'afterhours-backup-'+today()+'.json');
if(a==='recoveryexport')download(localStorage.getItem(KEY)||'','afterhours-recovery.json');
if(a==='persist'){const result=await navigator.storage?.persist?.();toast(result?'Persistent storage granted. Keep regular backups.':'Browser did not grant persistent storage. Keep regular backups.');}
if(a==='reminders')reminderSettings();
if(a==='calendar'){download(C.calendar(state),'afterhours-alerts.ics','text/calendar');toast('Calendar downloaded. Import into a dedicated calendar; replace old events after edits.');}
if(a==='copygroceries'){await copy('AFTERHOURS · 7-DAY GROCERIES\n'+C.groceries(state.plan.days.flatMap(d=>d.meals),state.profile,state.extraGroceries).map(g=>`${g.name}: ${g.packages} × ${g.pack} g — ${money(g.purchase)} est. (${Math.round(g.pantry)} g pantry used)`).join('\n'));}
if(a==='testnotification'){try{if(!('Notification'in window)||!('serviceWorker'in navigator))throw Error('Notifications unavailable. On iPhone, install with Safari’s Add to Home Screen first.');const perm=await Notification.requestPermission();if(perm!=='granted')throw Error('Permission not granted. Use device settings to enable it, or use calendar alerts.');const reg=await navigator.serviceWorker.ready;await reg.showNotification('Afterhours · Test notification',{body:'Immediate device test. Scheduled background push is not connected.',icon:'/icon-192.png',tag:'afterhours-test'});toast('Test submitted to your device. Confirm that you saw it; delivery is not verified.');render();}catch(e){toast(e.message);}}
if(a==='delete')modal(`<h2>Delete local records?</h2><p>This removes your plan, history, journal, and preferences from this browser. Your backup files and imported calendar alerts remain.</p><form id="delete-form">${field('Type DELETE to confirm','confirm','','text','required pattern="DELETE"')}<button class="danger-button" type="submit">Delete records</button></form>`);
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();Promise.resolve(action(el)).catch(err=>toast(err.message));}});
document.addEventListener('submit',e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const data=new FormData(f),get=n=>data.get(n);try{
if(f.id==='region-form'){const currency=get('currency'),rate=currency==='PHP'?1:Number(get('rate')),city=get('city');if(!C.currencies.includes(currency)||!C.cities.some(c=>c.id===city)||!Number.isFinite(rate)||rate<=0||rate>10000)throw Error('Choose a city and enter a positive currency rate.');if(save('Location and currency saved. Replace old calendar alerts if your city changed.',()=>{state.region={city,currency,rate};if(state.profile)state.profile.city=city;selectedDay='';}))close();return;}
if(f.id==='foodfilters-form'){if(save('Food filters saved. Compatible meals and groceries refreshed.',()=>{Object.assign(state.profile,{allergies:data.getAll('allergies'),otherAllergy:get('otherAllergy').trim(),avoid:get('avoid'),diet:get('diet'),prepTime:Number(get('prepTime')),kitchen:data.getAll('kitchen')});state.plan=C.refreshMeals(state.plan,state.profile,state.favorites,state.mealLogs,today());}))close();return;}
if(f.id==='choose-recipes-form'){const allowed=C.allowedRecipes(state.profile).map(r=>r.id);if(save('Recipe choices saved. Your recommendations are ready.',()=>{state.favorites=[...state.favorites.filter(id=>!allowed.includes(id)),...data.getAll('recipes').filter(id=>allowed.includes(id))];}))close();return;}
if(f.id==='tdee-form'){const values={...state.profile,...Object.fromEntries(data)};for(const key of ['height','weight','age','activity'])values[key]=Number(values[key]);const estimate=C.energyEstimate(values);if(!estimate)throw Error('Complete all calculator fields with valid adult measurements.');save('TDEE estimate and targets saved. Meal portions remain editable.',()=>{Object.assign(state.profile,values,{nutrition:'estimates'});state.plan.targets=estimate;});close();return;}
if(f.id==='setup-form'){readSetup(f);step++;setup();return;}
if(f.id==='workout-form'){captureSession();const es=session.exercises.map(e=>({id:e.id,formQuality:e.formQuality,plannedSets:e.sets.length,sets:e.sets.filter(s=>s.done).map(({done,...s})=>s)})).filter(e=>e.sets.length);if(!es.length)throw Error('Check at least one completed set before saving.');if(doneWorkout(session.day))throw Error('This waking day already has a completed session.');const before=C.journey(state);if(!save('',()=>state.workouts.push({day:session.day,exercises:es,saved:new Date().toISOString()})))return;const after=C.journey(state),unlocked=after.achievements.filter(a=>a.unlocked&&!before.achievements.find(b=>b.id===a.id).unlocked);session=null;modal(`<p class="eyebrow">SESSION SAVED</p><h2>Your work counts.</h2><p>${es.reduce((n,e)=>n+e.sets.length,0)} sets across ${es.length} exercises saved.${state.profile.journey?' +'+(after.xp-before.xp)+' XP.':''}</p>${state.profile.journey?`<p>${after.rank}${after.rank!==before.rank?' · Rank up!':''}</p>${unlocked.map(a=>`<p class="notice">Achievement unlocked: ${a.name}</p>`).join('')}`:''}<p>Review the next-session guidance for each movement. Increase only after all planned sets meet the rep target with reported controlled form and effort 8 or less. A partial session still counts; recover before your next strength day.</p>${btn('Done','close','','primary')}`);return;}
if(f.id==='reschedule-form'){const dd=state.plan.days.find(d=>d.day===f.dataset.day),s=C.settingsFor(state.profile,dd.day);if(C.isAsleep(get('time'),s))throw Error('That time falls inside your sleep window. Choose a time while awake.');save('The same session has been moved. Replace old calendar alerts.',()=>state.plan=C.reschedule(state.plan,dd.day,get('time')));close();return;}
if(f.id==='swap-form'){save('Meal swapped. Nutrition and groceries recalculated.',()=>state.plan=C.swapMeal(state.plan,state.profile,f.dataset.id,get('recipe')));close();return;}
if(f.id==='editmeal-form'){const dd=state.plan.days.find(d=>d.meals.some(m=>m.id===f.dataset.id));if(C.isAsleep(get('time'),C.settingsFor(state.profile,dd.day)))throw Error('This meal falls inside your sleep window.');save('Meal updated. Replace old calendar alerts.',()=>{const m=dd.meals.find(m=>m.id===f.dataset.id);m.time=get('time');m.servings=Number(get('servings'));});close();return;}
if(f.id==='checkin-form'){if(get('day')>today())throw Error('Check-ins cannot be dated in the future.');save('Check-in saved.',()=>{state.checkins=state.checkins.filter(c=>c.day!==get('day'));state.checkins.push({day:get('day'),weight:get('weight')?Number(get('weight')):null,hunger:Number(get('hunger')),energy:Number(get('energy'))});state.checkins.sort((a,b)=>a.day.localeCompare(b.day));});close();return;}
if(f.id==='food-form'){save('Daily food record saved.',()=>{state.foodLogs=state.foodLogs.filter(l=>l.day!==get('day'));state.foodLogs.push({day:get('day'),kcal:Number(get('kcal')),protein:Number(get('protein')),complete:data.has('complete')});});close();return;}
if(f.id==='journal-form'){save('Note saved.',()=>state.journal.push({day:selectedDay||today(),text:get('text').trim()}));return;}
if(f.id==='reminder-form'){save('Reminder preferences saved. Replace old calendar alerts.',()=>{state.profile.reminders={workout:data.has('workout'),meals:[0,1,2].map(i=>data.has('meal'+i))};state.profile.quietStart=get('quietStart');state.profile.quietEnd=get('quietEnd');});close();return;}
if(f.id==='prices-form'){save('Pantry and prices saved. Grocery totals updated.',()=>{for(const [id,i]of Object.entries(ingredients)){state.profile.pantry[id]=Number(get('pantry-'+id));const enteredPrice=Number(get('price-'+id)),originalPrice=state.profile.prices[id]?.price??i.price,price=enteredPrice===amount(originalPrice)?originalPrice:baseAmount(enteredPrice),pack=Number(get('pack-'+id)),source=get('source-'+id);const old=state.profile.prices[id];if(price!==(old?.price??i.price)||pack!==(old?.pack??i.pack)||source!==(old?.source||'Unverified planning estimate'))state.profile.prices[id]={price,pack,source,date:today()};}});return;}
if(f.id==='delete-form'&&get('confirm')==='DELETE'){localStorage.removeItem(KEY);state=C.fresh();storageError='';selectedDay='';undoState=null;session=null;render();close();toast('Local records deleted. Remove calendar events separately.');return;}
if(f.id==='import-form'){save('Backup imported.',()=>{state=JSON.parse(f.dataset.backup);selectedDay='';session=null;});close();return;}
}catch(err){if(f.id==='setup-form')$('#setup-error').textContent=err.message;else toast(err.message);}});
document.addEventListener('change',async e=>{if(e.target.closest('#region-form')){if(e.target.name==='country')$('#region-cities').innerHTML=cityOptions(e.target.value,'');if(['city','country'].includes(e.target.name))$('#region-zone').textContent='Schedule time zone: '+C.cityInfo({city:$('#region-form [name=city]').value}).zone;if(e.target.name==='currency')$('#region-rate').innerHTML=rateField(e.target.value,e.target.value===region().currency?region().rate:null);}
if(e.target.id==='recipe-servings'){const n=Number(e.target.value);if(n>=.25&&n<=10)showRecipe(activeRecipe.id,n);}
if(e.target.dataset.substitute!==undefined){const index=Number(e.target.dataset.substitute),id=e.target.value;captureSession();const ex=exercises.find(x=>x.id===id);session.exercises[index]={id,sets:Array.from({length:session.exercises[index].sets.length},()=>({reps:ex.reps[0],weight:0,rpe:7}))};drawSession();}
if(e.target.id==='import-file'){try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Backup exceeds the 10 MB limit.');const x=C.validateBackup(JSON.parse(await file.text()));modal(`<h2>Replace records with this backup?</h2><p>${x.workouts.length} sessions, ${x.checkins.length} check-ins, ${x.journal.length} notes. Export your current records first if needed.</p><form id="import-form"><button class="primary" type="submit">Import & replace</button></form>`);$('#import-form').dataset.backup=JSON.stringify(x);}catch(err){toast('Import rejected: '+err.message);}}
});
document.addEventListener('input',e=>{const form=e.target.closest('form');if(!form||!['tdee-form','setup-form'].includes(form.id))return;if(form.id==='setup-form'&&step!==0)return;const data=Object.fromEntries(new FormData(form));const p={...(form.id==='setup-form'?draft:state.profile||C.defaults),...data};for(const k of ['height','weight','age','activity'])p[k]=Number(p[k]);if(form.id==='tdee-form')$('#tdee-result').innerHTML=tdeeResult(p);else{const box=$('#setup-tdee-result');if(box)box.innerHTML=p.nutrition==='estimates'?tdeeResult(p):'';if(e.target.name==='nutrition'&&p.nutrition==='estimates')form.querySelector('details').open=true;}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'today';render();window.scrollTo(0,0);});
window.addEventListener('online',render);window.addEventListener('offline',render);
window.addEventListener('storage',e=>{if(e.key===KEY){toast('Records changed in another tab. Reload to use the latest version.');}});
if(!storageError&&state.profile&&state.plan&&!state.plan.days.some(d=>d.meals.length)&&state.plan.days.some(d=>d.day>=today())&&C.allowedRecipes(state.profile).length){save('Compatible meals and your grocery list have been restored.',()=>{state.plan=C.refreshMeals(state.plan,state.profile,state.favorites,state.mealLogs,today());});}
render();
if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('controllerchange',()=>{if(waitingUpdate)location.reload();});navigator.serviceWorker.register('/sw.js').then(reg=>{const ready=()=>{if(reg.waiting){waitingUpdate=reg.waiting;$('#toast').innerHTML='An app update is ready. Saved records will stay on this device. '+btn('Update now','updateapp','','text-btn');$('#toast').classList.add('show');}};ready();reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',ready));navigator.serviceWorker.ready.then(()=>{const el=$('#offline-status');if(el)el.textContent='App cache ready.';});}).catch(()=>toast('Offline cache could not be installed. Keep this app online and retry.'));}

document.addEventListener('change',e=>{if(e.target.name==='theme'){theme=e.target.value;try{localStorage.setItem('afterhours.theme',theme);}catch{toast('Theme applied, but this browser could not save the preference.');}applyTheme();}});

document.addEventListener('toggle',e=>{const d=e.target;if(!d.matches?.('details[data-video]'))return;const slot=d.querySelector('.video-slot');if(!d.open){slot.replaceChildren();return;}if(!navigator.onLine){slot.textContent='You are offline. Reopen this tutorial when connected; use the written instructions below for now.';return;}const iframe=document.createElement('iframe');iframe.src='https://www.youtube-nocookie.com/embed/'+d.dataset.video+'?playsinline=1&rel=0';iframe.title=d.querySelector('summary').textContent;iframe.allow='encrypted-media; fullscreen; picture-in-picture';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';slot.replaceChildren(iframe);},true);
$('#modal').addEventListener('close',()=>{$('#modal').querySelectorAll('iframe').forEach(f=>f.remove());});
